-- Function and constraint properties (as postgres).
SELECT ok((SELECT p.provolatile = 'i' AND NOT p.prosecdef AND NOT p.proisstrict AND p.proconfig @> ARRAY['search_path=pg_catalog']
  FROM pg_proc p WHERE p.oid = 'private.valid_message_citations(jsonb)'::regprocedure),
  'validator: IMMUTABLE, SECURITY INVOKER, NOT STRICT (STRICT would return NULL), pinned search_path'); -- 1
SELECT ok(NOT has_function_privilege('anon','private.valid_message_citations(jsonb)','EXECUTE')
  AND has_function_privilege('authenticated','private.valid_message_citations(jsonb)','EXECUTE')
  AND has_function_privilege('service_role','private.valid_message_citations(jsonb)','EXECUTE')
  AND NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(p.proacl) x WHERE p.oid = 'private.valid_message_citations(jsonb)'::regprocedure
                  AND x.grantee = 0 AND x.privilege_type = 'EXECUTE'), 'validator grants unchanged: authenticated + service_role, no PUBLIC/anon'); -- 2
SELECT is((SELECT pg_get_constraintdef(oid) || ' validated=' || convalidated FROM pg_constraint
  WHERE conrelid = 'public.chat_messages'::regclass AND conname = 'chat_messages_citations_valid'),
  'CHECK (private.valid_message_citations(citations)) validated=true', 'chat_messages_citations_valid present and validated'); -- 3

-- The exact reproduction from Agent 3's report.
SELECT is(private.valid_message_citations('[{}]'::jsonb), false, 'valid_message_citations(''[{}]'') is false (was true)'); -- 4
SELECT throws_ok($$INSERT INTO public.chat_messages(organization_id, thread_id, role, content, status, citations)
  VALUES ('eba00000-0000-4000-8000-00000000000a','eb700000-0000-4000-8000-0000000000a2','assistant','Independent malformed citation probe','complete','[{}]')$$,
  '23514', NULL, 'Agent 3''s INSERT with citations [{}] is rejected (23514)'); -- 5

-- SQL NULL and JSON null, explicitly.
SELECT is(private.valid_message_citations(NULL), false, 'SQL NULL -> false, not NULL'); -- 6
SELECT is(private.valid_message_citations('null'::jsonb), false, 'JSON null -> false'); -- 7
SELECT is((SELECT count(*)::int FROM (SELECT j FROM bad UNION ALL SELECT j FROM good UNION ALL SELECT NULL::jsonb) s
  WHERE private.valid_message_citations(j) IS NULL), 0, 'the validator returns NULL for none of the cases'); -- 8
SELECT throws_ok($$INSERT INTO public.chat_messages(organization_id, thread_id, role, content, citations)
  VALUES ('eba00000-0000-4000-8000-00000000000a','eb700000-0000-4000-8000-0000000000a1','assistant','x', NULL)$$,
  '23502', NULL, 'SQL NULL citations rejected (NOT NULL)'); -- 9

-- Re-validation as in the migration: existing valid rows survive, a stored malformed row blocks it.
INSERT INTO public.chat_messages (id, organization_id, thread_id, role, content, citations) SELECT
  'eb5e0000-0000-4000-8000-000000000001','eba00000-0000-4000-8000-00000000000a','eb700000-0000-4000-8000-0000000000a1','assistant','Existing answer [1] [2]', j
  FROM good WHERE ord = 3;
SELECT lives_ok($$ALTER TABLE public.chat_messages DROP CONSTRAINT chat_messages_citations_valid,
  ADD CONSTRAINT chat_messages_citations_valid CHECK (private.valid_message_citations(citations))$$,
  'existing valid citations pass a full re-validation'); -- 10
SELECT throws_ok($t$DO $d$ BEGIN
    ALTER TABLE public.chat_messages DROP CONSTRAINT chat_messages_citations_valid;
    INSERT INTO public.chat_messages (id, organization_id, thread_id, role, content, citations) VALUES
      ('eb5e0000-0000-4000-8000-0000000000ff','eba00000-0000-4000-8000-00000000000a','eb700000-0000-4000-8000-0000000000a1','assistant','planted','[{}]');
    ALTER TABLE public.chat_messages ADD CONSTRAINT chat_messages_citations_valid CHECK (private.valid_message_citations(citations));
  END $d$$t$, '23514', NULL, 'a stored [{}] row makes the re-validation fail (the migration would abort)'); -- 11
SELECT ok(EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.chat_messages'::regclass AND conname = 'chat_messages_citations_valid')
  AND NOT EXISTS (SELECT 1 FROM public.chat_messages WHERE id = 'eb5e0000-0000-4000-8000-0000000000ff'),
  'after the failed re-validation the constraint is intact and the planted row is gone'); -- 12

-- Existing persisted citations still read back unchanged and still validate (as table owner).
SELECT is((SELECT citations FROM public.chat_messages WHERE id = 'eb5e0000-0000-4000-8000-000000000001'),
  (SELECT j FROM good WHERE ord = 3), 'existing persisted citations read back unchanged'); -- 13
SELECT is((SELECT private.valid_message_citations(citations) FROM public.chat_messages WHERE id = 'eb5e0000-0000-4000-8000-000000000001'),
  true, 'existing persisted citations still validate'); -- 14

-- Assistant-only rule preserved (the CHECK applies to every writer, even the table owner).
SELECT throws_ok($$INSERT INTO public.chat_messages (thread_id, organization_id, role, content, citations)
  SELECT 'eb700000-0000-4000-8000-0000000000a1','eba00000-0000-4000-8000-00000000000a','user','x', j FROM good WHERE ord = 1$$,
  '23514', NULL, 'user message with valid citations rejected'); -- 15
SELECT throws_ok($$INSERT INTO public.chat_messages (thread_id, organization_id, role, content, citations)
  VALUES ('eb700000-0000-4000-8000-0000000000a1','eba00000-0000-4000-8000-00000000000a','user','x','[{}]')$$,
  '23514', NULL, 'user message with [{}] rejected'); -- 16

-- The server path (the only writer of assistant/tool rows since 20261120200003).
-- Runs the server RPC AS sso_control (EXECUTE is checked for that role), then
-- restores the caller's role. pgTAP itself is not resolvable by sso_control (no
-- USAGE on extensions), so the assertions stay outside the role switch; on error
-- the enclosing subtransaction restores the role.
CREATE FUNCTION pg_temp.ctl(p_org uuid, p_user uuid, p_thread uuid, p_role text, p_content text, p jsonb DEFAULT '[]', p_ku boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql AS $f$
DECLARE v_prev text := current_user; v jsonb;
BEGIN
  PERFORM set_config('role', 'sso_control', true);
  v := public.append_chat_message_server(p_org, p_user, p_thread, p_role, p_content, 'complete', NULL, '[]'::jsonb, NULL, p, p_ku);
  PERFORM set_config('role', v_prev, true);
  RETURN v;
END $f$;
CREATE FUNCTION pg_temp.ins(p jsonb, p_role text DEFAULT 'assistant', p_ku boolean DEFAULT false) RETURNS jsonb LANGUAGE sql AS $f$
  SELECT pg_temp.ctl('eba00000-0000-4000-8000-00000000000a', 'eb222222-2222-4222-8222-222222222222',
    'eb700000-0000-4000-8000-0000000000a1', p_role, 'x', p, p_ku) $f$;
SELECT throws_ok($$SELECT pg_temp.ins('[]', 'tool', true)$$, '23514', NULL, 'tool message with knowledge_unavailable rejected'); -- 17
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"eb222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT lives_ok($$INSERT INTO public.chat_messages (thread_id, organization_id, role, content) VALUES
  ('eb700000-0000-4000-8000-0000000000a2','eba00000-0000-4000-8000-00000000000a','user','plain hello');
  SELECT set_config('t.u', (SELECT id::text FROM public.chat_messages WHERE content = 'plain hello'), true);
  SELECT set_config('t.a', pg_temp.ctl('eba00000-0000-4000-8000-00000000000a', 'eb222222-2222-4222-8222-222222222222',
    'eb700000-0000-4000-8000-0000000000a2', 'assistant', 'plain answer')->>'id', true)$$,
  'normal chat: user message by the owner, assistant answer by the server, both without citations'); -- 18
RESET ROLE;
SELECT is((SELECT string_agg(role || ':' || citations::text || ':' || knowledge_unavailable, ',' ORDER BY role DESC) FROM public.chat_messages
  WHERE id IN (current_setting('t.u')::uuid, current_setting('t.a')::uuid)),
  'user:[]:false,assistant:[]:false', 'normal chat messages get [] / false'); -- 19
SELECT lives_ok($$SELECT pg_temp.ins('[]', 'assistant', true)$$, 'assistant answer with knowledge_unavailable and no citations'); -- 20
SELECT is((SELECT count(*)::int FROM bad), 67, '67 malformed cases are checked'); -- 21
SELECT is((SELECT count(*)::int FROM good), 9, '9 valid cases are checked'); -- 22

-- Every malformed case: the function says false, and the server INSERT fails with 23514.
SELECT is(private.valid_message_citations(j), false, 'validator rejects: ' || label) FROM bad ORDER BY ord;
SELECT throws_ok(format('SELECT pg_temp.ins(%L::jsonb)', j::text), '23514', NULL, 'INSERT rejects: ' || label) FROM bad ORDER BY ord;

-- Every valid case still passes both ways.
SELECT is(private.valid_message_citations(j), true, 'validator accepts: ' || label) FROM good ORDER BY ord;
SELECT lives_ok(format('SELECT pg_temp.ins(%L::jsonb)', j::text), 'INSERT accepts: ' || label) FROM good ORDER BY ord;

SELECT * FROM finish();
ROLLBACK;
